#include <stdio.h>
#include "d11-after-delimiter.h"

int main(void){
    char text[] = "RUN AUTO";
    int ch = fgetc(stdin);
    int a = after_delimiter(text,sizeof text ,ch) ;
    if (a == NULL)
    {
        puts ("NO_SUFFIX")
    }else{
        int b = text + a ;
        printf ("%s",b);
        text [a] = 'X'; 
        int b = text + a ;
        printf ("%s",b);
    }
    return 0;

}
